11	// ForeachAbs Host 端 — 遍历 tensor 列表，为每个 tensor 计算 tiling 并启动 kernel
12	
13	#include "torch_kernel_helper.h"
14	#include "tiling/platform/platform_ascendc.h"
15	#include "aclrtlaunch_foreach_abs.h"
16	
17	namespace ascend_kernel {
18	
19	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
20	
21	std::vector<at::Tensor> foreach_abs(const std::vector<at::Tensor>& inputs)
22	{
23	    std::vector<at::Tensor> outputs;
24	    outputs.reserve(inputs.size());
25	
26	    // ---- 获取硬件参数 ----
27	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
28	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
29	    uint64_t ubSize;
30	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
31	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
32	
33	    for (const auto& input : inputs) {
34	        // ---- 输入校验 ----
35	        TORCH_CHECK(input.scalar_type() == at::kHalf ||
36	                    input.scalar_type() == at::kBFloat16 ||
37	                    input.scalar_type() == at::kFloat,
38	                    "foreach_abs: only float16, bfloat16 and float32 are supported, got ",
39	                    input.scalar_type());
40	        TORCH_CHECK(input.is_contiguous(),
41	                    "foreach_abs: input tensor must be contiguous");
42	
43	        int64_t totalLength = input.numel();
44	        int64_t dtypeSize = static_cast<int64_t>(input.element_size());
45	
46	        auto output = at::empty_like(input);
47	
48	        if (totalLength == 0) {
49	            outputs.push_back(output);
50	            continue;
51	        }
52	
53	        // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
54	        int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
55	        int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
56	                                        / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
57	
58	        int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
59	        int64_t formerNum = usedCoreNum - 1;
60	        int64_t formerLength = totalLengthCoreAlign;
61	        int64_t tailLengthVal = totalLength - formerNum * formerLength;
62	
63	        // ---- UB 级 tiling (核内切分, 32B 对齐) ----
64	        // bufferCoefficient 从 UB 分配表推导:
65	        //   fp32: inQueue(8) + outQueue(8) + tempBuf(4) = 20
66	        //   fp16/bf16: inQueue(4) + outQueue(4) + castBufIn(4) + castBufOut(4) = 16
67	        int64_t bufferCoefficient = (dtypeSize == 4) ? 20 : 16;
68	        int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
69	        int64_t alignElements = 32 / dtypeSize;
70	        int64_t tileLength = (maxTileElements / alignElements) * alignElements;
71	        // tailLength 已在上方计算为左值 tailLengthVal
72	
73	        uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
74	
75	        // EXEC_KERNEL_CMD 硬约束: 所有参数必须是左值
76	        EXEC_KERNEL_CMD(foreach_abs, blockDim,
77	                        input, output,
78	                        formerNum, formerLength, tailLengthVal, tileLength, dtypeSize);
79	
80	        outputs.push_back(output);
81	    }
82	
83	    return outputs;
84	}
85	
86	}  // namespace ascend_kernel
