11	// ForeachAbs AscendC Kernel — 逐元素绝对值，支持 float32/float16/bfloat16
12	// host 端遍历 tensor 列表，为每个 tensor 独立启动此 kernel
13	
14	#include "kernel_operator.h"
15	
16	constexpr int32_t BUFFER_NUM = 2;
17	
18	template <typename T>
19	class KernelForeachAbs {
20	public:
21	    __aicore__ inline KernelForeachAbs() {}
22	
23	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
24	                                int64_t formerNum, int64_t formerLength,
25	                                int64_t tailLength, int64_t tileLength)
26	    {
27	        int64_t blockIdx = AscendC::GetBlockIdx();
28	
29	        if (blockIdx < formerNum) {
30	            this->blockLength = formerLength;
31	            int64_t offset = formerLength * blockIdx;
32	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
33	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
34	        } else {
35	            this->blockLength = tailLength;
36	            int64_t tailIdx = blockIdx - formerNum;
37	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
38	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
39	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
40	        }
41	
42	        this->tileLength = tileLength;
43	
44	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
45	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
46	        if constexpr (sizeof(T) == sizeof(float)) {
47	            // float32: no extra buffers needed
48	        } else {
49	            // fp16/bf16: need fp32 compute buffers for upcast
50	            pipe.InitBuffer(castBufIn, tileLength * sizeof(float));
51	            pipe.InitBuffer(castBufOut, tileLength * sizeof(float));
52	        }
53	    }
54	
55	    __aicore__ inline void Process()
56	    {
57	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
58	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
59	
60	        for (int64_t i = 0; i < tileNum - 1; ++i) {
61	            CopyIn(i, this->tileLength);
62	            Compute(i, this->tileLength);
63	            CopyOut(i, this->tileLength);
64	        }
65	        if (tileNum > 0) {
66	            CopyIn(tileNum - 1, tailTileLength);
67	            Compute(tileNum - 1, tailTileLength);
68	            CopyOut(tileNum - 1, tailTileLength);
69	        }
70	    }
71	
72	private:
73	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
74	    {
75	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
76	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
77	        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
78	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
79	        inQueueX.EnQue(xLocal);
80	    }
81	
82	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
83	    {
84	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
85	
86	        if constexpr (sizeof(T) == sizeof(float)) {
87	            // float32: compute Abs directly
88	            AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
89	            AscendC::Abs(yLocal, xLocal, curTileLength);
90	            outQueueY.EnQue<float>(yLocal);
91	        } else {
92	            // fp16/bf16: Cast up → float32 → Abs → Cast down
93	            AscendC::LocalTensor<float> xLocalFp32 = castBufIn.Get<float>();
94	            AscendC::LocalTensor<float> yLocalFp32 = castBufOut.Get<float>();
95	            AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
96	
97	            AscendC::Cast(xLocalFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
98	            AscendC::Abs(yLocalFp32, xLocalFp32, curTileLength);
99	            AscendC::Cast(yLocal, yLocalFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
100	
101	            outQueueY.EnQue<T>(yLocal);
102	        }
103	        inQueueX.FreeTensor(xLocal);
104	    }
105	
106	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
107	    {
108	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
109	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
110	        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
111	        outQueueY.FreeTensor(yLocal);
112	    }
113	
114	private:
115	    AscendC::TPipe pipe;
116	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
117	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
118	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufIn;
119	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufOut;
120	    AscendC::GlobalTensor<T> xGm;
121	    AscendC::GlobalTensor<T> yGm;
122	    int64_t blockLength;
123	    int64_t tileLength;
124	};
125	
