// ForeachAddScalarList AscendC Kernel — 逐元素标量加法
// out_i = x_i + alphaValue (alphaValue 为 float32 标量)
// 支持: float32 直接计算, float16/bfloat16/int32/int64 经 float32 中间计算
// Host 端遍历 tensor 列表，为每个 tensor 独立启动此 kernel

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelForeachAddScalarList {
public:
    __aicore__ inline KernelForeachAddScalarList() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                float alphaValue)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }

        this->tileLength = tileLength;
        this->alphaValue = alphaValue;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) != sizeof(float)) {
            // fp16/bf16/int32/int64: need fp32 intermediate buffers
            pipe.InitBuffer(castBufIn, tileLength * sizeof(float));
            pipe.InitBuffer(castBufOut, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if (this->blockLength == 0) {
            return;
        }
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        CopyIn(tileNum - 1, tailTileLength);
        Compute(tileNum - 1, tailTileLength);
        CopyOut(tileNum - 1, tailTileLength);
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // float32: compute Adds directly with float scalar
            AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
            AscendC::Adds(yLocal, xLocal, this->alphaValue, curTileLength);
            outQueueY.EnQue<float>(yLocal);
        } else {
            // fp16/bf16/int32/int64: Cast up → fp32 → Adds(alpha) → Cast down
            AscendC::LocalTensor<float> xLocalFp32 = castBufIn.Get<float>();
            AscendC::LocalTensor<float> yLocalFp32 = castBufOut.Get<float>();
            AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

            // Cast to float32 for intermediate computation
            AscendC::Cast(xLocalFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            // Compute in float32
            AscendC::Adds(yLocalFp32, xLocalFp32, this->alphaValue, curTileLength);
            // Cast back to original dtype (ROUND for float types, NONE for int truncation)
            if constexpr (sizeof(float) == 4 && (sizeof(T) == 2)) {
                // fp16/bf16: use CAST_ROUND for float→half conversion
                AscendC::Cast(yLocal, yLocalFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
            } else {
                // int32/int64: use CAST_NONE for float→int truncation
                AscendC::Cast(yLocal, yLocalFp32, AscendC::RoundMode::CAST_NONE, curTileLength);
            }

            outQueueY.EnQue<T>(yLocal);
        }
        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufIn;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufOut;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t tileLength;
    float alphaValue;
};

extern "C" __global__ __aicore__ void foreach_add_scalar_list(GM_ADDR x, GM_ADDR y,
                                                               int64_t formerNum, int64_t formerLength,
                                                               int64_t tailLength, int64_t tileLength,
                                                               int64_t dtypeSize,
                                                               float alphaValue)
{
    if (dtypeSize == 2) {
        KernelForeachAddScalarList<half> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, alphaValue);
        op.Process();
    } else if (dtypeSize == 4) {
        KernelForeachAddScalarList<float> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, alphaValue);
        op.Process();
    } else if (dtypeSize == 8) {
        KernelForeachAddScalarList<int64_t> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, alphaValue);
        op.Process();
    }
}
