// ForeachAddScalarList Host 端 — 遍历 tensor 列表，为每个 tensor 计算 tiling 并启动 kernel

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_foreach_add_scalar_list.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

std::vector<at::Tensor> foreach_add_scalar_list(const std::vector<at::Tensor>& inputs,
                                                 const at::Tensor& alpha)
{
    std::vector<at::Tensor> outputs;
    int64_t listLen = static_cast<int64_t>(inputs.size());
    outputs.reserve(static_cast<size_t>(listLen));

    // ---- 获取硬件参数 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- 准备 alpha 值 (统一转为 float32) ----
    at::Tensor alphaFloat = alpha.to(at::kFloat).contiguous();
    const float* alphaData = alphaFloat.const_data_ptr<float>();

    for (int64_t k = 0; k < listLen; ++k) {
        const at::Tensor& input = inputs[static_cast<size_t>(k)];
        float alphaValue = alphaData[static_cast<size_t>(k)];

        // ---- 输入校验 ----
        auto scalarType = input.scalar_type();
        TORCH_CHECK(scalarType == at::kHalf || scalarType == at::kBFloat16 ||
                    scalarType == at::kFloat || scalarType == at::kInt ||
                    scalarType == at::kLong,
                    "foreach_add_scalar_list: only float16, bfloat16, float32, int32, int64 supported, got ",
                    scalarType);
        TORCH_CHECK(input.is_contiguous(),
                    "foreach_add_scalar_list: input tensor must be contiguous");

        int64_t totalLength = input.numel();
        int64_t dtypeSize = static_cast<int64_t>(input.element_size());

        auto output = at::empty_like(input);

        if (totalLength == 0) {
            outputs.push_back(output);
            continue;
        }

        // ---- 判断是否为浮点类型 ----
        int64_t isFloatType = (scalarType == at::kFloat || scalarType == at::kHalf ||
                               scalarType == at::kBFloat16) ? 1 : 0;

        // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
        int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
        int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                        / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

        int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
        int64_t formerNum = usedCoreNum - 1;
        int64_t formerLength = totalLengthCoreAlign;
        int64_t tailLengthVal = totalLength - formerNum * formerLength;

        // ---- UB 级 tiling (核内切分, 32B 对齐) ----
        // bufferCoefficient 从 UB 分配表推导:
        //   fp32: inQueue(2*4) + outQueue(2*4) = 16
        //   fp16/bf16: inQueue(2*2) + outQueue(2*2) + castBufIn(4) + castBufOut(4) = 16
        //   int32: inQueue(2*4) + outQueue(2*4) + castBufIn(4) + castBufOut(4) = 24
        //   int64: inQueue(2*8) + outQueue(2*8) + castBufIn(4) + castBufOut(4) = 40
        int64_t bufferCoefficient;
        if (dtypeSize == 4 && isFloatType == 1) {
            bufferCoefficient = 16;   // float32: direct compute
        } else if (dtypeSize == 4 && isFloatType == 0) {
            bufferCoefficient = 24;   // int32: cast to fp32
        } else if (dtypeSize == 2) {
            bufferCoefficient = 16;   // fp16/bf16: cast to fp32
        } else {
            bufferCoefficient = 40;   // int64: cast to fp32
        }

        int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
        int64_t alignElements = 32 / dtypeSize;
        if (alignElements < 1) {
            alignElements = 1;
        }
        int64_t tileLength = (maxTileElements / alignElements) * alignElements;

        uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

        // EXEC_KERNEL_CMD 硬约束: 所有参数必须是左值
        EXEC_KERNEL_CMD(foreach_add_scalar_list, blockDim,
                        input, output,
                        formerNum, formerLength, tailLengthVal, tileLength,
                        dtypeSize, isFloatType, alphaValue);

        outputs.push_back(output);
    }

    return outputs;
}

}  // namespace ascend_kernel
